var JARC = [['#E63946', '#FF8FAB'], ['#FFC300', '#FF7F11'], ['#2EC4B6', '#4CC9F0'], ['#B388EB', '#FF5DA2'], ['#7BD389', '#FFD23F']];
function shopJar(x, i, tag, done){
  var R = rnd(31 + i * 7), c = JARC[i], s = '<g ' + K + '>';
  s += '<rect x="' + (x + 26) + '" y="66" width="78" height="16" fill="#E9FBFF"/><rect x="' + (x + 16) + '" y="78" width="98" height="130" rx="20" fill="#E9FBFF"/></g>';
  var nn = done ? 5 : 13;
  for (var k = 0; k < nn; k++){ var cx = x + 32 + R() * 66, cy = done ? 182 + R() * 16 : 100 + R() * 96; s += circ(cx.toFixed(1), cy.toFixed(1), 9, c[k % 2], ' stroke="#1b1b1b" stroke-width="2.5"') + shine(cx, cy, 9); }
  s += '<path d="M' + (x + 26) + ',96 v86" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".9"/>';
  s += '<g ' + K + ' stroke-width="3.5"><rect x="' + (x + 36) + '" y="122" width="58" height="30" rx="8" fill="#FFFDF2"/></g><text x="' + (x + 65) + '" y="144" text-anchor="middle" font-family="Chewy,cursive" font-size="19" fill="#1b1b1b">' + tag + '</text>';
  if (done) s += '<g ' + K + ' transform="rotate(-28 ' + (x + 30) + ' 44)"><rect x="' + (x + 6) + '" y="36" width="86" height="22" rx="6" fill="' + c[0] + '"/></g>';
  else s += '<g ' + K + '><rect x="' + (x + 20) + '" y="46" width="90" height="24" rx="6" fill="' + c[0] + '"/><rect x="' + (x + 50) + '" y="38" width="30" height="10" rx="4" fill="' + c[1] + '"/></g>';
  return s;
}
