  s += '<g ' + K + '><path d="M370,338 H546 L536,402 H380Z" fill="#fff"/><path d="M428,338 L424,402 M488,338 L492,402 M374,370 H542" fill="none" stroke-width="4"/></g>';
  var pm = [[400, 354, '#FF5DA2'], [458, 354, '#FFC300'], [516, 354, '#7BD389'], [402, 386, '#4CC9F0'], [458, 386, '#B388EB'], [514, 386, '#FF7F11']];
  pm.forEach(function(p, i){ for (var q = 0; q < 3; q++){ var px = p[0] - 14 + q * 13, py = p[1] - 4 + (q % 2) * 7; s += i % 2 ? '<rect x="' + (px - 6) + '" y="' + (py - 5) + '" width="13" height="10" rx="3" fill="' + p[2] + '" stroke="#1b1b1b" stroke-width="2.5"/>' : circ(px, py, 6, p[2], ' stroke="#1b1b1b" stroke-width="2.5"'); } });
  s += '<g ' + K + ' stroke-width="4"><path d="M440,338 V290"/><rect x="396" y="270" width="98" height="34" rx="8" fill="#FFE14D"/></g><text x="445" y="294" text-anchor="middle" font-family="Chewy,cursive" font-size="19" fill="#C2185B">PICK ’N’ MIX</text>';
