BURST["dr-options"] = [
{
"t": "Court hearings are normally in open court.",
"true": true,
"fix": "Hearings are normally in **open court** and judgments are **published**."
},
{
"t": "The general rule is that the loser pays the winner's costs.",
"true": true,
"fix": "The general rule is that the **loser pays the winner's costs**."
},
{
"t": "The court can grant an injunction before trial.",
"true": true,
"fix": "The court can grant **interim remedies** (orders before trial), such as an **injunction**."
},
{
"t": "A claimant can always issue a claim unless there is a valid arbitration agreement.",
"true": true,
"fix": "No agreement is needed: a claimant can **always issue a claim** unless there is a valid **arbitration agreement**."
},
{
"t": "Higher-court decisions bind later cases.",
"true": true,
"fix": "**Precedent**: higher-court decisions bind later cases, useful if a client wants a point of law settled."
},
{
"t": "The court can make orders against non-parties, e.g. to disclose documents.",
"true": true,
"fix": "The court can make orders against **non-parties** (e.g. to disclose documents)."
},
{
"t": "Summary judgment is judgment without a trial where the other side has no real prospect of success.",
"true": true,
"fix": "**Summary judgment**: judgment without a trial where the other side has no real prospect of success."
},
{
"t": "Both parties must agree before a case can go to court.",
"true": false,
"fix": "**No.** A claimant can always issue a claim unless there is a valid arbitration agreement."
},
{
"t": "Court judgments are kept private.",
"true": false,
"fix": "**No.** Litigation is **public**: hearings are in open court and judgments are **published**."
},
{
"t": "In court, the parties choose their judge.",
"true": false,
"fix": "**No.** In litigation the parties **cannot choose the judge**."
},
{
"t": "Litigation tends to keep business relationships going.",
"true": false,
"fix": "**No.** Litigation tends to **end business relationships**."
}
];
