BURST["dr-responding"] = [
{
"t": "A claimant can discontinue at any time by filing and serving a notice of discontinuance.",
"true": true,
"fix": "**True.** File the notice and serve it on every other party."
},
{
"t": "A discontinuing claimant usually pays the defendant's costs up to that date.",
"true": true,
"fix": "**True.** Unless the court orders otherwise (CPR 38.6)."
},
{
"t": "A Tomlin order's schedule is confidential.",
"true": true,
"fix": "**True.** The schedule is not part of the public order."
},
{
"t": "A settlement for a child is not binding until the court approves it.",
"true": true,
"fix": "**True.** CPR 21.10."
},
{
"t": "A claimant who has received an interim payment can always discontinue without permission.",
"true": false,
"fix": "**False.** Permission is needed, unless the defendant consents in writing."
},
{
"t": "A consent order cannot be enforced like a judgment.",
"true": false,
"fix": "**False.** A consent order is enforceable directly, like any judgment."
},
{
"t": "An accepted Part 36 offer stays the claim automatically.",
"true": true,
"fix": "**True.** The claim is stayed automatically."
},
{
"t": "A claimant who discontinues after a defence is filed can sue again on the same facts without permission.",
"true": false,
"fix": "**False.** It needs the court's permission (CPR 38.7)."
},
{
"t": "A settlement made before issue is simply a binding contract.",
"true": true,
"fix": "**True.** No court order is involved."
},
{
"t": "A claimant can discontinue without permission after an interim injunction has been granted.",
"true": false,
"fix": "**False.** Permission is needed where an interim injunction has been granted (or an undertaking given)."
},
{
"t": "The defendant can apply to set aside a notice of discontinuance within 28 days of service.",
"true": true,
"fix": "**True.** E.g. where the claimant is abusing the process."
}
];
