BURST["dr-evidence"] = [
{
"t": "Hearsay is admissible in civil cases.",
"true": true,
"fix": "Hearsay is **admissible** in civil proceedings and not excluded just because it is hearsay (s.1)."
},
{
"t": "If the maker won't be called, serve a hearsay notice with the reason.",
"true": true,
"fix": "The notice identifies the hearsay, says you rely on it and gives the **reason** the maker will not be called."
},
{
"t": "The other side has 14 days to apply to call the maker.",
"true": true,
"fix": "Within **14 days** after service of the hearsay notice (s.3, CPR 33.4)."
},
{
"t": "A statement made at the time of the events usually carries more weight.",
"true": true,
"fix": "Whether it was made **contemporaneously** is a s.4 weight factor."
},
{
"t": "Hearsay without notice is inadmissible.",
"true": false,
"fix": "Failure to give notice does **not** make it inadmissible (s.2(4)); it affects **weight** and **costs**."
},
{
"t": "Multiple hearsay always carries full weight.",
"true": false,
"fix": "Whether it involves **multiple hearsay** is a factor the court weighs (s.4)."
},
{
"t": "A statement passed through more than one person is multiple hearsay.",
"true": true,
"fix": "\"Ben told me that Ann told him...\" is **multiple hearsay**."
},
{
"t": "If the maker will be called, serving their witness statement is enough notice.",
"true": true,
"fix": "Serving the witness statement containing the hearsay is **sufficient notice**."
},
{
"t": "To attack an absent maker's credibility, give notice within 14 days.",
"true": true,
"fix": "Notice of intention within **14 days** after service of the hearsay notice (s.5, CPR 33.5)."
},
{
"t": "A hearsay statement is excluded unless its maker attends trial.",
"true": false,
"fix": "Hearsay is **admissible**; the other side may apply to call the maker for cross-examination."
}
];
