BURST["records-reconciliation"] = [
{
"t": "Each client ledger shows the client's name and a description of the matter.",
"true": true,
"fix": "**True.** Rule 8.1(a): identified by the client's name and a description of the matter."
},
{
"t": "Statements are needed for business accounts as well as client accounts.",
"true": true,
"fix": "**True.** Rule 8.2 covers all client accounts **and business accounts**."
},
{
"t": "Records must be made at the time and in date order.",
"true": true,
"fix": "**True.** Accurate, contemporaneous (at the time) and chronological (in date order)."
},
{
"t": "Statements every two months are enough.",
"true": false,
"fix": "**False.** Statements are needed **at least every five weeks** (r.8.2)."
},
{
"t": "Bills of costs go on the client side of the ledger.",
"true": false,
"fix": "**False.** Bills of costs go on the **business side** of the ledger."
},
{
"t": "The cash book is the bank's own statement.",
"true": false,
"fix": "**False.** The cash book is the **firm's own record** of the client bank account."
},
{
"t": "The list of client ledger balances shows what the firm owes clients and third parties.",
"true": true,
"fix": "**True.** Its running total shows the firm's total **liabilities** to clients and third parties."
},
{
"t": "Transfers between client ledgers are recorded with the reason and authority.",
"true": true,
"fix": "**True.** They follow from the duty to keep **accurate** records."
},
{
"t": "Money that is not client money is recorded on the client side of the ledger.",
"true": false,
"fix": "**False.** Receipts and payments that are not client money go on the **business side**."
},
{
"t": "The cash book shows a running total of all transactions through client accounts.",
"true": true,
"fix": "**True.** Rule 8.1(c)."
},
{
"t": "Accounting records need to be kept for only two years.",
"true": false,
"fix": "**False.** Keep them securely for **at least six years** (rule 13)."
}
];
BOARD_HOOKS["records-reconciliation"] = ["Statements: every 5 weeks", "Reconcile: every 5 weeks", "Bank, cash book, ledgers:", "all three must agree", "Manager or COFA signs off", "Keep records for 6 years"];
