BURST["poca-offences-reporting"] = [
{
"t": "Money saved by not paying tax can be criminal property.",
"true": true,
"fix": "Yes: **saved costs** (e.g. tax not paid) can be a benefit."
},
{
"t": "There is no minimum value.",
"true": true,
"fix": "Yes: any crime counts, and there is **no minimum value**."
},
{
"t": "Suspicion means a possibility that is more than fanciful.",
"true": true,
"fix": "Yes: a **possibility, which is more than fanciful**, that the facts exist."
},
{
"t": "A client cancelling and asking for the money to go abroad is a red flag.",
"true": true,
"fix": "Yes: an **unusual instruction**."
},
{
"t": "Conduct abroad counts if it would be an offence here.",
"true": true,
"fix": "Yes: criminal conduct includes conduct abroad that would be an offence in the UK."
},
{
"t": "Large cash payments from an unknown third party are a red flag.",
"true": true,
"fix": "Yes: **large cash** or funds from an **unknown third party**."
},
{
"t": "Only serious crimes count.",
"true": false,
"fix": "No. **Any** crime counts, however small, including tax evasion and benefit fraud."
},
{
"t": "Suspicion must be firmly grounded.",
"true": false,
"fix": "No. The suspicion need **not** be clear or firmly grounded."
},
{
"t": "A vague feeling of unease is enough to suspect.",
"true": false,
"fix": "No. A **vague feeling of unease is not enough**."
},
{
"t": "A client happy to pay unusually high fees is nothing to worry about.",
"true": false,
"fix": "No. **Unusually high fees** are a red flag."
}
];
