/* build the room chain: SCENES["blp/<topicid>"] for rooms 2-16, in content/blp.js topic order */
var ROOM_KEYS = [], ROOM_IDX = {};
(function(){
  if (!ROOMS_ON) return;
  var subj = null; (window.SQE_SUBJECTS || []).forEach(function(s){ if (s && s.id === 'blp') subj = s; });
  var ids = subj ? subj.topics.map(function(t){ return t.id; }) : Object.keys(ROOMS);
  ids.forEach(function(tid, i){
    var k = 'blp/' + tid, m = ROOMS[tid] || {name: 'Room ' + (i + 1), icon: '🍬', slug: 'room-' + tid, bg: '#FFF1C9'};
    ROOM_KEYS.push(k); ROOM_IDX[k] = i;
    if (i === 0){ if (SCENES[k]){ SCENES[k].room = 1; if (ROOMV3[tid]) SCENES[k] = Object.assign({}, SCENES[k], {inside: v3inside(tid, SCENES[k].inside.hotspots, SCENES[k].inside.alt)}); } return; }
    var d = ROOMDATA[tid] || {}, ins = d.inside || {};
    if (ROOMV3[tid]){ ins = v3inside(tid, ins.hotspots || [], ins.alt || m.name); d = Object.assign({}, d); ['scenario', 'game'].forEach(function(x){ var b = ROOMV3[tid].spots[x]; if (d[x] && b){ d[x] = Object.assign({}, d[x], {x: b[0], y: b[1], w: b[2], h: b[3]}); } }); }
    var hs = ins.hotspots;
    if (!hs){ var dk = (window.SQE_LEARN || {})[k] || (window.SQE_ROOM_LEARN || {})[k]; hs = dk && dk.sections ? dk.sections.map(function(sec, si){ return {id: 's' + si, icon: '🍬', label: sec.h, cards: [[si]]}; }) : []; }
    var spots = hs.slice(); if (d.scenario) spots.push(d.scenario); if (d.game) spots.push(d.game);
    var cols = spots.length > 9 ? 4 : 3, rows = Math.ceil(spots.length / cols) || 1;
    spots.forEach(function(h, j){ if (h.x == null){ h.x = 2 + (j % cols) * (96 / cols); h.y = 4 + Math.floor(j / cols) * (92 / rows); h.w = 96 / cols - 3; h.h = 92 / rows - 5; h.ph = true; } });
    SCENES[k] = { room: i + 1, name: m.name, icon: m.icon, bg: m.bg, treat: 'treat', treats: 'treats', enter: m.icon + ' Enter ' + m.name.replace(/^The /, 'the '),
      inside: { img: ins.img || (m.art ? 'img/scene/' + m.slug + '.webp' : ''), ratio: ins.ratio || 16 / 9, alt: ins.alt || m.name, hotspots: hs, board: ins.board || null, hooks: ins.hooks || null },
      scenario: d.scenario || null, game: d.game || null };
  });
})();

