      SCENES[k] = { room: i + 1, stop: sid, name: m.name, icon: m.icon || '', bg: m.bg, treat: 'spot', treats: 'spots', enter: 'Enter ' + m.name.replace(/^The /, 'the '),
        inside: { img: pic ? 'img/scene/' + m.slug + '.webp' : '', ratio: m.ratio || 2752 / 1536, alt: (d.inside && d.inside.alt) || m.name, hotspots: hs,
          board: pic && v.board && v.board.w ? v.board : null, hooks: pic && v.hooks && v.hooks.length ? v.hooks : null },
        scenario: sc, game: gm };
