'.scn-board:hover,.scn-board:focus-visible{outline:3px dashed rgba(255,255,255,.7);outline-offset:-3px}',
'.scn-board.paged .scn-bt{overflow-wrap:normal;word-break:keep-all;hyphens:none}.scn-board.paged .scn-bt .ln{display:none}.scn-board.paged .scn-bt .ln.on{display:block;animation:scnChalk 1s steps(22,end) both}.scn-board.paged .scn-bt .ln.on+.ln.on{animation-delay:.85s}.scn-board.paged .scn-bt .ln.on+.ln.on+.ln.on{animation-delay:1.7s}.scn-board.paged .scn-bt{line-height:1.08}.scn-board.paged .scn-bt::after{content:none!important}',
'@keyframes scnChalk{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}.scn-boardin .scn-bt .ln{animation:scnChalk .9s steps(24,end) both;animation-delay:calc(var(--i,0) * .75s + .15s)}@media (prefers-reduced-motion:reduce){.scn-board.paged .scn-bt .ln.on,.scn-boardin .scn-bt .ln{animation:none}}',

'.scn-bt{display:block;max-width:100%;font-size:2cqw;overflow-wrap:break-word}.scn-bt .ln{display:block}.scn-bt .ln+.ln{margin-top:.14em}',
