'@media (max-width:640px){.scn-boardbig{border-width:9px;aspect-ratio:4/3}.scn-boardx{top:-18px;right:-12px}}',
'.scn-art>svg,.scn-art>img{display:block;width:100%;height:auto}',
'.scn-hs{position:absolute;display:flex;align-items:flex-end;justify-content:center;padding:0 2px 4px;margin:0;border:3px dashed transparent;border-radius:16px;background:transparent;cursor:pointer;color:#111;font:inherit;-webkit-tap-highlight-color:transparent}',
