'.scn-hs.door .scn-lab{position:absolute;left:50%;bottom:44%;transform:translateX(-50%);width:max-content;max-width:150%;font-size:15px;animation:scnBob 1.2s ease-in-out infinite}',
'.scn-hs.door.open .scn-leaf{transform:rotateY(108deg)}',
