'.scn-msg.on{opacity:1;background:#B8F2C9;border-color:#1b1b1b}',
'.scn-toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:72;max-width:calc(100vw - 32px);padding:10px 18px;border:3px solid #1b1b1b;border-radius:99px;background:#B8F2C9;color:#111;font-weight:700;box-shadow:3px 3px 0 #1b1b1b;animation:scnToast 2.6s ease forwards}',
'@keyframes scnToast{0%{opacity:0;transform:translate(-50%,20px)}10%,80%{opacity:1;transform:translate(-50%,0)}100%{opacity:0}}',
