'.jpanel .btn.jscene b{font-family:"Chewy",var(--font);font-weight:400;font-size:24px;line-height:1.1}',
'.jpanel .btn.jscene span{font-size:14px;font-weight:600}',
'.jtl li a.jscene-s{flex:none;font-size:13px;font-weight:700;padding:2px 8px;border:2px solid #1b1b1b;border-radius:99px;background:#FFE0EC;color:#111;text-decoration:none}',
'.jsv a.jnum{cursor:pointer}',
'@media (max-width:640px){.scn-sheet .lrn-tbl td{display:block;position:relative;padding-left:calc(45% + 22px)}.scn-sheet .lrn-tbl td::before{position:absolute;left:12px;top:10px;width:45%}.scn-lab{display:none}.scn-pin{display:block}.scn-hs.door .scn-lab{display:block;font-size:11px;line-height:1.15;padding:3px 7px;max-width:none;width:max-content;bottom:auto;top:-30%;white-space:nowrap}.scn-hs{padding:0;border-width:2px;border-radius:10px}.scn-hs .scn-tick{width:22px;height:22px;font-size:13px;line-height:17px;border-width:2px;right:1px;top:1px}.scn-head h2{font-size:25px}.scn-ov{padding:40px 0 0;align-items:flex-start}.scn-sheet{margin:auto 0 0;border-radius:22px 22px 0 0;border-width:3px 0 0;box-shadow:none;padding:12px 12px 20px;min-height:60vh}.scn-list{grid-template-columns:1fr}.scn-art{border-width:3px;border-radius:14px;box-shadow:3px 3px 0 #1b1b1b}.scn-hs.next{border-width:4px;border-radius:10px}.scn-nexttag .d{display:none}.scn-nexttag .m{display:inline}.scn-nexttag{font-size:11px;padding:1px 6px 2px;border-width:2px;top:auto;bottom:0;transform:translate(-50%,60%);animation-name:scnTagM}.scn-art .scn-leave{display:none}.scn-leave{font-size:22px}}',
'@keyframes scnTagM{0%,100%{transform:translate(-50%,60%)}50%{transform:translate(-50%,30%)}}',
'@media (prefers-reduced-motion:reduce){.scn-nexttag,.scn-leave,.scn-art .scn-leave,.scn-hs.next,.scn-hs.door .scn-lab,.scn-confetti i{animation:none}.scn-hs.door .scn-leaf{transition:none}.scn-art.zoom{animation:none}}',
'body:has(.scn-ov){overflow:hidden}',
/* BL1 package pass (19 Nov): opened objects keep their full colour, dark outlines + sweet buttons in the pop-ups, readable "opened" rows */
'.scn-hs.done{background:transparent}',
'.scn-hs.done .scn-lab{opacity:1}',
'.scn-list .done button{opacity:1;background:#E6F8EC;color:#111}',
'.scn-list .done .t small{color:#2F4A3A}',
'.scn-list .t small{color:var(--ink);opacity:.8}',
'.scn-sheet .lrn-card{border:3px solid #1b1b1b;box-shadow:4px 4px 0 #1b1b1b}',
'.scn-sheet .lrn-rev summary{border:2.5px dashed #1b1b1b;background:#FFE0EC;color:#8A1449}',
'.scn-sheet .btn{border:2.5px solid #1b1b1b;border-radius:999px;box-shadow:0 3px 0 #1b1b1b;background:#FFFDF6;color:#1b1b1b;font-weight:700}',
'.scn-sheet .btn.primary{background:#C2185B;color:#fff}',
'.scn-sheet .btn[disabled]{box-shadow:none}',
'.scn-sheet .btn:active{transform:translateY(2px);box-shadow:0 1px 0 #1b1b1b}',
'.scn-sheet .scn-nav .scn-eat{background:#2E9E5B;color:#fff}',
'.scn-sheet .opt{border:2.5px solid #1b1b1b;border-radius:14px}',
'.scn-st .k,.scn-mn,.scn-xq .qmeta{color:var(--ink)}',
'.scn-revisit .t small{color:var(--ink);opacity:.8}',
'.scn-nextup{margin:12px 0 4px}',
'@media (min-width:641px){html.scn-rooms .scn-art:not(.hub-art) .scn-hs:not(.door) .scn-pin{width:22px;height:22px;font-size:12px;line-height:17px}}',
'.qt-card{text-align:center}.qt-card .qt-s{font-size:clamp(19px,2.4vw,24px);line-height:1.35;font-weight:700;margin:10px auto 16px;max-width:30em}.qt-btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}.qt-b{min-width:130px;font-size:20px!important;padding:12px 22px!important;border:3px solid #1b1b1b!important;box-shadow:3px 3px 0 #1b1b1b!important;border-radius:999px!important;color:#fff!important}.qt-t{background:#2E9E5B!important}.qt-f{background:#E8453C!important}.qt-r{font-size:18px;line-height:1.4;max-width:32em;margin:6px auto 0;padding:12px 14px;border-radius:14px;border:3px solid #1b1b1b}.qt-r.ok{background:#DDF6E4}.qt-r.no{background:#FFE3E0}',
'.scn-xres{margin-top:12px}',
/* britney-asks (19 Nov): Britney's speech bubble + big faces on the exit pass screen */
'.scn-brit{margin:16px auto 6px;max-width:640px;background:#FFF0F6;border:2.5px solid #1b1b1b;border-radius:20px;box-shadow:4px 4px 0 #1b1b1b;padding:14px 14px 16px;color:#1b1b1b}',
'.scn-brit-k{margin:0 0 6px;font-size:15px}',
'.scn-brit-row{display:flex;align-items:center;gap:16px;justify-content:center}',
'.scn-brit-hen{flex:0 0 auto;width:190px;height:190px}',
'.scn-brit-hen img{width:100%;height:100%;object-fit:contain;display:block}',
'.scn-brit.rated .scn-brit-hen img{animation:scnBritHop .5s ease}',
'@keyframes scnBritHop{0%{transform:translateY(0) scale(1)}40%{transform:translateY(-12px) scale(1.06)}100%{transform:translateY(0) scale(1)}}',
'.scn-brit-say{position:relative;flex:0 1 auto;max-width:min(26em,100%);min-width:0;background:#fff;border:2.5px solid #1b1b1b;border-radius:22px;padding:14px 16px;text-align:left}',
'.scn-brit-say:before{content:"";position:absolute;left:-14px;top:50%;margin-top:-10px;border:10px solid transparent;border-right:14px solid #1b1b1b;border-left:0}',
'.scn-brit-say:after{content:"";position:absolute;left:-9px;top:50%;margin-top:-7px;border:7px solid transparent;border-right:10px solid #fff;border-left:0}',
'.scn-brit-say .q{display:block;font-family:"Chewy",var(--font);font-size:30px;line-height:1.1;color:#A3215B}',
'.scn-brit-say .a{display:block;margin-top:6px;font-size:16px;font-weight:700;color:#1b1b1b}',
'.scn-brit .scn-rate{margin-top:12px;gap:10px}',
'.scn-brit .scn-rate .rate{background:#fff;border:2.5px solid #1b1b1b;border-radius:16px;min-width:92px;padding:8px 10px;font-size:15px;font-weight:800;color:#1b1b1b;display:inline-flex;flex-direction:column;align-items:center;gap:4px}',
'.scn-brit .scn-rate .rate .ragw{display:block;width:48px;height:48px;font-size:0}',
'.scn-brit .scn-rate .rate .ragf{width:48px;height:48px;display:block}',
'.scn-brit .scn-rate .rate > span:not(.ragw){font-size:14px;font-weight:800;color:#1b1b1b;margin-top:2px}',
