'@keyframes scnPop{from{opacity:0;transform:translateY(8px) scale(.97)}to{opacity:1;transform:none}}',
'.scn-q{margin:12px 0 8px;font-weight:800;font-size:17px;color:#1b1b1b}',
'.scn-opts{display:grid;gap:8px}',
'.scn-opt{display:block;width:100%;text-align:left;font:inherit;font-size:16px;padding:10px 14px;border:2.5px solid #1b1b1b;border-radius:14px;background:#FFFDF6;color:#1b1b1b;box-shadow:0 3px 0 #1b1b1b;cursor:pointer}',
'.scn-opt.right{background:#DFF7EA;border-color:#2E7D32;box-shadow:0 3px 0 #2E7D32}',
'.scn-opt.wrong{background:#FFE0EC;border-color:#A3215B;box-shadow:0 3px 0 #A3215B}',
'.scn-opt.dim{opacity:.55}.scn-opt[disabled]{cursor:default}',
'.scn-fb{margin:10px 0 0;padding:10px 12px;border:2.5px solid #1b1b1b;border-radius:14px;background:#F1E6FF;color:#1b1b1b}',
'.scn-fb.ok{background:#DFF7EA}',
'.gm-top{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:10px 0}',
'.gm-time{display:inline-flex;align-items:center;gap:4px;padding:4px 12px;border:2.5px solid #1b1b1b;border-radius:99px;background:#FFE14D;color:#111;font-weight:800}',
'.gm-time.up{background:#FFD1E3}',
'.gm-score{font-weight:800;color:#1b1b1b}',
'.gm-how{margin:4px 0 8px;color:#1b1b1b}',
'.gm-item{margin:8px auto 12px;max-width:520px;padding:16px 18px;border:3px solid #1b1b1b;border-radius:20px;background:#FFF5FA;color:#1b1b1b;font-size:18px;font-weight:800;text-align:center;box-shadow:4px 4px 0 #1b1b1b;touch-action:none;cursor:grab;user-select:none;-webkit-user-select:none}',
'.gm-item.drag{position:fixed;z-index:80;pointer-events:none;margin:0;opacity:.92;transform:rotate(-3deg)}',
'.gm-bins{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}',
'.gm-bin{min-height:72px;padding:10px;border:3px solid #1b1b1b;border-radius:18px;background:#E8F7FF;color:#1b1b1b;font:inherit;font-weight:800;font-size:15px;box-shadow:0 4px 0 #1b1b1b;cursor:pointer}',
'.gm-bin.hot{background:#FFF200}',
'.gm-bin.flash-ok{background:#B8F2C9}.gm-bin.flash-no{background:#FFC2D6}',
'.gm-fb{min-height:24px;margin:10px 0 0;font-weight:700;color:#1b1b1b}',
'.gm-last{display:block;font-weight:400;font-size:.88em;color:#555;margin-bottom:2px;font-style:italic}',
'.gm-fb.ok{color:#2E7D32}.gm-fb.no{color:#A3215B}',
'.gm-left,.gm-right{display:grid;gap:8px}',
'.gm-match{display:grid;grid-template-columns:1.4fr 1fr;gap:10px}',
'.gm-chip{display:block;width:100%;text-align:left;font:inherit;font-size:15px;padding:9px 12px;border:2.5px solid #1b1b1b;border-radius:14px;background:#FFFDF6;color:#1b1b1b;box-shadow:0 3px 0 #1b1b1b;cursor:pointer}',
'.gm-chip.sel{background:#FFF200;box-shadow:0 0 0 3px #FF2D8A}',
