'.gm-slots li{display:flex;align-items:center;gap:8px}',
'.gm-slots li:before{counter-increment:gs;content:counter(gs);flex:none;width:28px;height:28px;border:2.5px solid #1b1b1b;border-radius:50%;background:#FFE14D;color:#111;display:grid;place-items:center;font-weight:800}',
'.gm-slots .empty{flex:1;min-height:40px;border:2.5px dashed #1b1b1b;border-radius:14px}',
'.gm-pool{display:grid;gap:8px;margin:8px 0}',
