'.gm-big{text-align:center}.gm-big .big{font-size:56px;line-height:1}.gm-big h2{font-family:"Chewy",var(--font);font-weight:400;font-size:30px;margin:4px 0}',
'.gm-nums{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin:10px 0}',
'.gm-num{min-width:110px;padding:12px 16px;border:3px solid #1b1b1b;border-radius:16px;background:#FFFDF6;color:#1b1b1b;font:800 20px/1.1 var(--font);box-shadow:0 4px 0 #1b1b1b;cursor:pointer}',
'.gm-num.right{background:#DFF7EA;border-color:#2E7D32}.gm-num.wrong{background:#FFE0EC;border-color:#A3215B}.gm-num.dim{opacity:.55}',
