'.fg-anim{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1;overflow:visible}.fg-anim .fgb{fill:#FFF8B0;opacity:.15;animation:fgTw 1.8s ease-in-out infinite}.fg-anim .fgw{animation-duration:1.6s}@keyframes fgTw{0%,100%{opacity:.1}50%{opacity:.95;fill:#FFFFFF}}.fg-anim .fgstar,.fg-anim .fgwheel{transform-box:fill-box;transform-origin:center;animation:fgSpin 40s linear infinite}@keyframes fgSpin{to{transform:rotate(360deg)}}.fg-anim .fgcab{transform-box:fill-box;transform-origin:50% 0;animation:fgSpinR 40s linear infinite}@keyframes fgSpinR{to{transform:rotate(-360deg)}}.fg-anim .fghen{transform-box:fill-box;transform-origin:45% 96%;animation:fgHen 11s ease-in-out infinite}@keyframes fgHen{0%,6%{transform:none}9%{transform:rotate(7deg)}12%{transform:none}15%{transform:rotate(7deg)}18%,24%{transform:none}38%,48%{transform:translateX(-90px)}51%{transform:translateX(-90px) rotate(7deg)}54%,60%{transform:translateX(-90px)}62%,70%{transform:translateX(-90px) scaleX(-1)}84%,88%{transform:scaleX(-1)}90%,100%{transform:none}}.fg-wb{position:absolute;left:9.6%;top:62.5%;width:14.2%;height:18.5%;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.25cqw;text-align:center;color:#1D3557;font:400 1.15cqw/1.1 "Gochi Hand","Delius",cursive;pointer-events:none}.fg-wb b{font-weight:400;font-size:1.3cqw;color:#B3261E;text-decoration:underline;text-underline-offset:.2cqw}@media (prefers-reduced-motion:reduce){.fg-anim .fgb,.fg-anim .fgstar,.fg-anim .fghen,.fg-anim .fgwheel,.fg-anim .fgcab{animation:none}.fg-anim .fgride{display:none}}',

'.hub-hs .scn-pin{display:block;left:50%;top:68%;bottom:auto;transform:translateX(-50%)}',
