  var RUNR = {"layla":{"w":659,"h":600,"hip":[300,358],"knee":[425,398],"a0":72.6,"b0":41.2,"sole":[[470,586],[500,599],[560,588],[604,526]],"g":598},"bert":{"w":616,"h":800,"hip":[385,548],"knee":[442,622],"a0":37.8,"b0":5.3,"sole":[[470,786],[500,798],[580,752],[612,700]],"g":798}}, RUN_AMP = 36, RUN_LEAN = 6;
