  /* 20 Nov (Monnie): from the day after she finishes a subject's last topic, Today gets "Bert's Butchers: <subject> test" automatically until she passes it (as well as the planned slot) */
  function bertDue(pd){
    var out = (pd.bert || []).slice(), have = {}; out.forEach(function(b){ have[b.s.id] = 1; });
    if (pd.d !== A.ymd()) return out;
    var B = bertS();
    A.SUBJ.forEach(function(s){
      if (have[s.id] || (B[s.id] && B[s.id].passed) || !subjDone(s)) return;
      var fin = 0; s.topics.forEach(function(t){ var v = S().done[s.id + '/' + t.id], at = v && (typeof v === 'number' ? v : v.at); if (at > fin) fin = at; });
      if (fin && A.ymd(new Date(fin)) >= pd.d) return; /* finished today: Bert comes tomorrow */
      out.push({s: s});
    });
    return out;
  }
  /* ---------- timetable: a "Bert's Butchers: <subject> test" slot on the study day after each subject's last learning day ---------- */
