    if (!test && !fed.length){ TRIP.out = {t0: n, w: pathW(fromShed(TRIP.L0))}; return; }
    if (test) fed = feedable().length ? feedable() : ['britney'];
    var bp = britState(loopT(), n, true);
    var lw = pathW(fromShed(FEED_SPOT)) + FADE, bw = pxd([bp.x, bp.b], FEED_BRIT) / 140 * 1000;
    var A0 = Math.max(lw, bw, 600) + 300;
    FEED = {t0: n, L0: SHED_DOOR, Lback: TRIP.L0, Lf: 'l', B0: [bp.x, bp.b], Bf: bp.face, A: A0, test: test, others: fed.filter(function(id){ return id !== 'britney'; }), lines: britLines()};
    FEED.eat = A0 + 2400 + GRAINS.length * 820;
    FEED.pat = FEED.eat + 700; FEED.end = FEED.pat + 3 * 2500 + 900;   /* she goes over and pats Britney through the three bubbles, then waves */   /* three bubbles, then she stops (Monnie 10:05) */
    FEED.back = Math.max(walkTo(PAT_SPOT, FEED.Lback, 0, TRIP_PX).w, pxd(FEED_BRIT, FEED.B0) / 140 * 1000) + 200;
    TRIP.out = {t0: n, feed: true};
