    if (need > 1) out += (c.coins >= p * need ? '<button type="button" class="btn' + (bags ? '' : ' primary') + '" data-mount="buyfeed" data-n="' + need + '"><img class=\"mg-ic\" src=\"img/mount/item-feed.webp\" alt=\"\"> Buy ' + need + ' bags · ' + (p * need) + '</button> ' : '');
    out += c.coins >= p ? '<button type="button" class="btn' + (bags || need > 1 ? '' : ' primary') + '" data-mount="buyfeed" data-n="1"><img class=\"mg-ic\" src=\"img/mount/item-feed.webp\" alt=\"\"> Buy 1 bag · ' + p + '</button>' : '<button type="button" class="btn" disabled>Need ' + (p - c.coins) + ' more coins for feed</button>';
