/* 21 Nov (Monnie): study time is counted automatically, with no button. While a study page is open and visible and she has
   clicked, typed, scrolled or moved the mouse in the last few minutes, the time goes into the hours log (one line per day and
   subject). Peckham, the Mount, Hen Bargains, the map and the Today/Hours/Progress/Settings pages are not counted. Time after her
   last touch only counts once she touches the site again (reading counts, walking away doesn't). Paused while the study timer runs. */
var AUTO = {act:Date.now(), tick:Date.now(), conf:0, prov:0, subj:"", last:0, IDLE:4 * 60000, GRACE:90000};
function autoSubj(r){
  if (/^(home|hours|progress|settings|plan|map|palace|mount|podcasts|sra)$/.test(r[0] || "")) return null;
  if (r[0] === "town"){ if (r[1] !== "butcher" && r[1] !== "jobs") return null; return ""; }
  if (r[0] === "cards" && r[1] === "all") return "";
  return BYID[r[1]] ? r[1] : "";
}
