  var d = ymd(), s = AUTO.subj || "", e = null;
  for (var i = S.logs.length - 1; i >= 0; i--){ var l = S.logs[i]; if (l.auto && l.d === d && (l.s || "") === s){ e = l; break; } }
  if (!e){ e = {id:"auto" + uid(), d:d, m:0, s:s, note:"Studying on the site (counted automatically)", auto:1}; S.logs.push(e); }
