  if (sj === null){ AUTO.prov = 0; return; }
  if (sj !== AUTO.subj){ autoFlush(); AUTO.prov = 0; AUTO.subj = sj; }
  var idle = now - AUTO.act;
  if (idle >= AUTO.IDLE){ AUTO.prov = 0; return; }   /* walked away: drop the time since her last touch */
