function autoAct(){ if (AUTO.prov){ AUTO.conf += AUTO.prov; AUTO.prov = 0; } AUTO.act = Date.now(); }
["pointerdown","keydown","wheel","touchstart","scroll","mousemove","input"].forEach(function(ev){ try { window.addEventListener(ev, autoAct, {capture:true, passive:true}); } catch(e){} });
