function dayBefore(ds){ var d = parseYmd(ds); d.setDate(d.getDate() - 1); return ymd(d); }
function goalMins(d){ var dk = ymd(d); if ((S.settings.daysOff || []).indexOf(dk) >= 0) return 0; if (dk === S.settings.exam1 || dk === S.settings.exam2) return 0; if (dk === dayBefore(S.settings.exam1) || dk === dayBefore(S.settings.exam2)) return 360; var w = d.getDay(); return Math.round(60 * (+(w === 0 || w === 6 ? S.settings.weekend : S.settings.weekday) || 0)); }
function weekStart(){ var d = new Date(); d.setHours(0,0,0,0); var w = (d.getDay() + 6) % 7; d.setDate(d.getDate() - w); return d; }
function weekDays(){ var a = [], st = weekStart(); for (var i = 0; i < 7; i++){ var d = new Date(st); d.setDate(st.getDate() + i); a.push(d); } return a; }
function weekGoal(){ var t = 0; weekDays().forEach(function(d){ t += goalMins(d); }); return t; }
function weekDone(){ var t = 0; weekDays().forEach(function(d){ t += minsOn(ymd(d)); }); return t + runningMins(); }
function plannedUntil(exam){ var t = 0, d = new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate() + 1); var end = parseYmd(exam); while (d < end){ t += goalMins(d); d.setDate(d.getDate() + 1); } return t; }
