  var k = w / 40, c = [[-12,3,9],[-3,-3,11],[9,-1,9],[15,4,6],[-17,6,5],[0,6,10]], o = '', f = '';
  c.forEach(function(q){ var x = (cx + q[0] * k).toFixed(1), y = (cy + q[1] * k).toFixed(1), r = q[2] * k; o += '<circle cx="' + x + '" cy="' + y + '" r="' + (r + 1.3).toFixed(1) + '"/>'; f += '<circle cx="' + x + '" cy="' + y + '" r="' + (r - 0.9).toFixed(1) + '"/>'; });
