function nbNight(){ var q = (location.search || "") + "&" + (location.hash || ""), m = /[?&]sky=(night|day)/.exec(q), h; if (m) return m[1] === "night"; m = /[?&]hour=(\d+(?:\.\d+)?)/.exec(q); if (m) h = (+m[1]) % 24; else { var fo = ""; try { fo = localStorage.getItem("sqe_sky") || ""; } catch(e){} if (fo === "night") return true; if (fo === "day") return false; var d = new Date(); h = d.getHours() + d.getMinutes() / 60; } return h >= 18 || h < 6; } /* Monnie 17:36: night from 6 PM */
var NB_STARS = [[1529,61,9],[1402,198,5],[1613,38,7],[1640,224,9],[1645,111,6],[1434,93,9],[1463,149,9],[1708,146,8],[1577,94,8],[1805,104,6],[2211,181,6],[2076,89,7],[2115,245,5],[2157,58,6],[2067,174,8],[2330,236,6],[2298,179,7],[2365,171,7],[1432,316,7],[1392,366,7],[1375,297,7],[1955,379,6],[1955,457,8],[2262,311,6],[2336,307,6],[2315,370,9],[438,229,9],[370,37,9],[415,109,7],[266,129,7],[143,39,6],[283,49,8],[444,157,6],[1845,40,7]]; /* picture units (2400x770), kept clear of the title, stats, Remember card, moon and buttons */
