  var lid = function(x, y){ return '<ellipse cx="' + x + '" cy="' + y + '" rx="6.5" ry="9" fill="#FBE590"/><path d="M' + (x - 6.5) + ',' + (y - 1) + 'q6.5,5.5 13,0" fill="none" stroke="#23202E" stroke-width="2.6" stroke-linecap="round"/>'; };
