  var parts = kids.map(function(n){ return img(n, true); }).join("") + kids.map(function(n){ return n === "sun" ? '<div class="fx-sun fxsun"><img src="img/banner-anim/sun.webp" alt="" draggable="false">' + face + '</div>' : img(n, false); }).join("");
