function focusLeft(){ return S.focus ? Math.max(0, S.focus.end - Date.now()) : 0; }
function fmtMS(ms){ var s = Math.ceil(ms / 1000); return Math.floor(s / 60) + ":" + pad(s % 60); }
function glass(frac, size, running, glit){
  // frac = share of sand still in the top bulb (1 = full, 0 = empty)
  // sand-rainbow (20 Nov): glittery rainbow sand; sparkles + colour drift only while running (CSS-gated)
  frac = Math.max(0, Math.min(1, frac));
  var top = 46 * frac, bot = 46 * (1 - frac), gid = "grain" + size;
  var star = function(x, y, r, d){ return '<path class="gspark" style="animation-delay:' + d + 's" d="M' + x + ' ' + (y - r) + ' Q' + x + ' ' + y + ' ' + (x + r) + ' ' + y + ' Q' + x + ' ' + y + ' ' + x + ' ' + (y + r) + ' Q' + x + ' ' + y + ' ' + (x - r) + ' ' + y + ' Q' + x + ' ' + y + ' ' + x + ' ' + (y - r) + 'Z"/>'; };
  return '<svg class="glass' + (running ? " run" : "") + (glit ? " glit" : "") + '" width="' + size + '" height="' + Math.round(size * 1.4) + '" viewBox="0 0 100 140" aria-hidden="true">' +
    '<defs><clipPath id="gtop"><path d="M22 14 H78 C78 40 56 56 52 68 H48 C44 56 22 40 22 14Z"/></clipPath>' +
    '<clipPath id="gbot"><path d="M48 72 H52 C56 84 78 100 78 126 H22 C22 100 44 84 48 72Z"/></clipPath>' +
    '<linearGradient id="' + gid + '" gradientUnits="userSpaceOnUse" x1="10" y1="14" x2="90" y2="126">' +
    '<stop offset="0" stop-color="#FF6FA8"/><stop offset=".2" stop-color="#FFB347"/><stop offset=".4" stop-color="#FFE45C"/><stop offset=".6" stop-color="#6FE3A1"/><stop offset=".8" stop-color="#6FB8FF"/><stop offset="1" stop-color="#B98CFF"/></linearGradient></defs>' +
    '<rect x="12" y="4" width="76" height="10" rx="4" class="gwood"/><rect x="12" y="126" width="76" height="10" rx="4" class="gwood"/>' +
    '<g class="gsandg" fill="url(#' + gid + ')" stroke="url(#' + gid + ')">' +
    '<g clip-path="url(#gtop)"><rect x="0" y="' + (68 - top).toFixed(1) + '" width="100" height="' + top.toFixed(1) + '" class="gsand"/></g>' +
    '<g clip-path="url(#gbot)"><rect x="0" y="' + (126 - bot).toFixed(1) + '" width="100" height="' + bot.toFixed(1) + '" class="gsand"/></g>' +
    (running && frac > 0 ? '<line x1="50" y1="66" x2="50" y2="125" class="gstream"/>' : '') + '</g>' +
    (running || glit ? '<g class="gsparks">' + star(38, 58, 5, 0) + star(62, 52, 4, .7) + star(50, 96, 4, 1.3) + star(34, 116, 5, .4) + star(66, 112, 4, 1.8) + '</g>' : '') +
    '<path d="M22 14 H78 C78 40 56 56 52 70 C56 84 78 100 78 126 H22 C22 100 44 84 48 70 C44 56 22 40 22 14Z" class="gglass"/>' +
  '</svg>';
}
function sandFrac(){ if (!S.focus) return 1; return focusLeft() / Math.max(1, S.focus.end - S.focus.begin); }
function sandBtn(){
  var f = S.focus, lab = f ? (f.mode === "focus" ? "Focus " : "Break ") + fmtMS(focusLeft()) : "Focus timer";
  return '<button class="sandbtn' + (f ? " on " + f.mode : "") + '" data-act="sandopen" aria-label="Open the sand timer">' + glass(sandFrac(), 28, !!f, true) + '<span id="sandlab">' + lab + '</span></button>';
}
function sandPanel(){
  if (!sandOpen) return "";
  var f = S.focus, h = '<div class="sandov" data-act="sandclose"><div class="sandbox" role="dialog" aria-label="Sand timer" data-stop="1">' +
    '<button class="sandx" data-act="sandclose" aria-label="Close">×</button>' +
    '<div class="sandbig" id="sandbig">' + glass(sandFrac(), 120, !!f) + '</div>';
  if (f){
    h += '<div class="sandtime" id="sandtime">' + fmtMS(focusLeft()) + '</div>' +
      '<p class="sandnote">' + (f.mode === "focus" ? "Focus time. It's counting towards today's study hours." : "Break time. Stretch, drink some water, look away from the screen.") + '</p>' +
      '<div class="sandrow"><button class="btn" data-act="sandcancel">' + (f.mode === "focus" ? "Stop early &amp; log" : "End break") + '</button></div>';
  } else {
    if (sandMsg) h += '<p class="sanddone">' + sandMsg + '</p>';
    h += '<p class="sandnote">Pick a session. Focus time is added to your hours log automatically.</p><div class="sandopts">' +
      SAND_OPTS.map(function(o){ return '<button class="btn ' + (o[0] === "focus" ? "primary" : "") + '" data-act="sandgo" data-m="' + o[0] + '" data-n="' + o[1] + '">' + (o[0] === "focus" ? ICO_BOOKS : ICO_TEA) + " " + o[2] + '</button>'; }).join("") +
      '</div><div class="sandrow"><button class="btn good" data-act="sandfree">▶ Just start the timer (no limit)</button></div>';
  }
  return h + '</div></div>';
}
function chime(){
  try {
    if (!audioCtx) return; var t = audioCtx.currentTime;
    [0, 0.35, 0.7].forEach(function(d, i){ var o = audioCtx.createOscillator(), g = audioCtx.createGain(); o.type = "sine"; o.frequency.value = [660, 880, 990][i];
      g.gain.setValueAtTime(0.0001, t + d); g.gain.exponentialRampToValueAtTime(0.3, t + d + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, t + d + 0.6);
      o.connect(g); g.connect(audioCtx.destination); o.start(t + d); o.stop(t + d + 0.65); });
  } catch(e){}
}
function sandStart(mode, mins){
  try { if (!audioCtx){ var AC = window.AudioContext || window.webkitAudioContext; if (AC) audioCtx = new AC(); } if (audioCtx && audioCtx.resume) audioCtx.resume(); } catch(e){}
  var now = Date.now();
  if (mode === "focus"){ if (!S.timer.start){ S.timer.subj = ($("#tsubj") || {}).value || S.timer.subj || ""; S.timer.start = now; } }
  else if (S.timer.start || S.timer.acc){ var m = logTimer("Study session"); sandMsg = m >= 1 ? "✓ " + m + " min added to your hours log." : ""; }
  S.focus = {mode:mode, begin:now, end:now + mins * 60000, mins:mins};
  save(); render();
}
/* strip break buttons (5/10/15 min): pause the study timer (break time isn't study), count down in the strip */
function stripBreak(mins){
  try { if (!audioCtx){ var AC = window.AudioContext || window.webkitAudioContext; if (AC) audioCtx = new AC(); } if (audioCtx && audioCtx.resume) audioCtx.resume(); } catch(e){}
  var now = Date.now();
  if (S.timer.start){ S.timer.acc += now - S.timer.start; S.timer.start = 0; }
  S.brkOver = 0; S.focus = {mode:"break", begin:now, end:now + mins * 60000, mins:mins, strip:1};
  save(); render();
}
function sandFinish(early){
  var f = S.focus; if (!f) return; S.focus = null;
  if (f.mode === "focus"){
    if (S.timer.start){ var stopAt = Math.min(Date.now(), f.end); S.timer.acc += Math.max(0, stopAt - S.timer.start); S.timer.start = 0; }
    var m = logTimer("Focus session");
    sandMsg = (early ? "" : "🎉 Focus session done! ") + (m >= 1 ? m + " min added to your hours log. " : "") + (early ? "" : "Take a break?");
  } else sandMsg = early ? "" : "☕ Break over. Ready for another focus session?";
  if (!early){ if (f.strip){ S.brkOver = 1; sandMsg = ""; } else sandOpen = true; chime(); }
  save(); render();
}
function sandTick(){
  if (!S.focus) return;
  if (focusLeft() <= 0){ sandFinish(false); return; }
  var l = document.getElementById("sandlab"); if (l) l.textContent = (S.focus.mode === "focus" ? "Focus " : "Break ") + fmtMS(focusLeft());
  var t = document.getElementById("sandtime"); if (t) t.textContent = fmtMS(focusLeft());
  var bc = document.getElementById("brkclock"); if (bc) bc.textContent = fmtMS(focusLeft());
  var fr = sandFrac();
  $all(".glass").forEach(function(g){
    var r = g.querySelectorAll("g rect"); if (r.length < 2) return;
    var top = 46 * fr, bot = 46 * (1 - fr);
    r[0].setAttribute("y", (68 - top).toFixed(1)); r[0].setAttribute("height", top.toFixed(1));
    r[1].setAttribute("y", (126 - bot).toFixed(1)); r[1].setAttribute("height", bot.toFixed(1));
  });
}

/* ============ SIDEBAR ============ */
var CONF = [{v:1, e:"🟢", l:"Green", c:"var(--good)"}, {v:0.5, e:"🟠", l:"Amber", c:"var(--warn)"}, {v:0, e:"🔴", l:"Red", c:"var(--bad)"}];
function trec(k){ var v = S.done[k]; if (!v) return null; if (typeof v === "number") return {n:1, conf:null, at:v}; return v; }
function confOf(k){ var r = trec(k); if (!r) return null; for (var i = 0; i < CONF.length; i++) if (CONF[i].v === r.conf) return CONF[i]; return {v:null, e:"✓", l:"Reviewed", c:"var(--accent)"}; }
function ago(ts){ var d = Math.round((parseYmd(ymd()) - parseYmd(ymd(new Date(ts)))) / 86400000); return d <= 0 ? "today" : d === 1 ? "yesterday" : d + " days ago"; }
function mring(n, tot, col, lab){
  var pct = tot ? Math.min(1, n / tot) : 0, R = 14, C = 2 * Math.PI * R;
  return '<span class="mring" title="' + esc(lab || (n + " of " + tot)) + '"><svg viewBox="0 0 36 36" width="36" height="36" aria-hidden="true"><circle cx="18" cy="18" r="' + R + '" fill="none" stroke="var(--alt)" stroke-width="5"/>' +
    (n ? '<circle cx="18" cy="18" r="' + R + '" fill="none" stroke="' + (col || "var(--good)") + '" stroke-width="5" stroke-linecap="round" stroke-dasharray="' + (pct * C).toFixed(1) + ' ' + C.toFixed(1) + '" transform="rotate(-90 18 18)"/>' : '') +
    '<text x="18" y="21.5" text-anchor="middle" font-size="9.5" font-weight="700" fill="var(--ink)">' + Math.round(pct * 100) + '%</text></svg><span class="mlab">' + esc(lab || (n + "/" + tot)) + '</span></span>';
}
function pbar(n, tot, col){ return '<div class="pbar thin"><i style="width:' + (tot ? Math.min(100, n / tot * 100) : 0).toFixed(1) + '%;' + (col ? "background:" + col : "") + '"></i></div>'; }
function segbar(segs){ var tot = 0; segs.forEach(function(x){ tot += x.n; }); return '<div class="segbar">' + segs.filter(function(x){ return x.n; }).map(function(x){ return '<i style="flex:' + x.n + ';background:' + x.c + '" title="' + esc(x.l) + ': ' + x.n + '"></i>'; }).join("") + (tot ? '' : '<i style="flex:1;background:var(--alt)"></i>') + '</div>'; }
function donut(segs, center, sub, label){
  var tot = 0; segs.forEach(function(x){ tot += x.n; });
  var R = 52, C = 2 * Math.PI * R, off = 0, h = '<div class="donut"><svg viewBox="0 0 132 132" width="132" height="132" role="img" aria-label="' + esc(label) + '"><circle cx="66" cy="66" r="' + R + '" fill="none" stroke="var(--alt)" stroke-width="16"/>';
  segs.forEach(function(x){
    if (!x.n || !tot) return;
    var len = x.n / tot * C, gap = segs.filter(function(y){ return y.n; }).length > 1 ? 2 : 0;
    h += '<circle cx="66" cy="66" r="' + R + '" fill="none" stroke="' + x.c + '" stroke-width="16" stroke-dasharray="' + Math.max(0.1, len - gap).toFixed(2) + ' ' + (C - Math.max(0.1, len - gap)).toFixed(2) + '" stroke-dashoffset="' + (-off).toFixed(2) + '" transform="rotate(-90 66 66)"><title>' + esc(x.l) + ': ' + x.n + ' (' + Math.round(x.n / tot * 100) + '%)</title></circle>';
    off += len;
  });
  h += '<text x="66" y="66" text-anchor="middle" font-size="22" font-weight="700" fill="var(--ink)">' + esc(center) + '</text><text x="66" y="84" text-anchor="middle" font-size="11" fill="var(--muted)">' + esc(sub) + '</text></svg><ul class="legend">';
  segs.forEach(function(x){ h += '<li><i style="background:' + x.c + '"></i>' + esc(x.l) + ' <b>' + x.n + '</b></li>'; });
  return h + '</ul></div>';
}


