function cbaItem(id){ return CBA_SHOP.filter(function(x){ return x.id === id; })[0]; }
/* a gold coin (the coin emoji looks like a moon on some Macs) */
function cbaCoin(){ return '<svg class="coin" viewBox="0 0 20 20" role="img" aria-label="coins"><circle cx="10" cy="10" r="9.3" fill="#D99A0B"/><circle cx="10" cy="10" r="7.7" fill="#FFCF33" stroke="#F2B200" stroke-width="1.1"/><path d="M5.9 7.2a5 5 0 0 1 5.4-3.5" fill="none" stroke="#FFF1A8" stroke-width="1.4" stroke-linecap="round"/><text x="10" y="14.2" text-anchor="middle" font-size="10.5" font-weight="800" font-family="Arial,Helvetica,sans-serif" fill="#A66C00">£</text></svg>'; }
function cbaS(){
  var c = S.cba = S.cba || {xp:0, days:{}, done:{}};
  c.days = c.days || {}; c.done = c.done || {}; c.prog = c.prog || {}; c.eggs = c.eggs || {}; c.own = c.own || {}; c.ate = c.ate || {};
  if (!Array.isArray(c.recent)) c.recent = [];
  if (typeof c.coins !== "number" || isNaN(c.coins)) c.coins = 20 + Math.floor((+c.xp || 0) / 10);
  for (var k in c.done) if (c.done[k] && !c.eggs[k]) c.eggs[k] = typeof c.done[k] === "number" ? c.done[k] : Date.now();
  if (!c.last){ var ds = Object.keys(c.days).sort(); if (ds.length) c.last = parseYmd(ds[ds.length - 1]).getTime() + 12 * 3600000; }
  return c;
}
/* topic eggs: ANY study of a topic (Today step, card, Quick fire, Model Q&A, rating, podcast or CBA level) lays that topic's egg on the farm */
function layEgg(k){ if (!k || !TBYKEY[k]) return; var c = cbaS(); if (!c.eggs[k]){ c.eggs[k] = Date.now(); GDIRTY = 1; } }
function qaTopicKey(id){ var x = qById(id); if (!x) return ""; if (!(id in QTOP)) topicQs(x.s, ""); return QTOP[id] ? x.s.id + "/" + QTOP[id] : ""; }
function cardTopicKey(d){ if (!d || !d.s) return ""; var t = cardTopic(d.s, +String(d.id).split("~")[1]); return t ? d.s.id + "/" + t : ""; }
function cbaStreak(){ var c = cbaS(), n = 0, d = new Date(); d.setHours(0,0,0,0); if (!c.days[ymd(d)]) d.setDate(d.getDate() - 1); while (c.days[ymd(d)]){ n++; d.setDate(d.getDate() - 1); } return n; }
function cbaReady(x){ return !!(CBA[x.key] && CBA[x.key].length); }
function cbaPick(){
  var seq = planSeq(), c = cbaS(), i;
  for (i = 0; i < seq.length; i++) if (cbaReady(seq[i]) && !c.done[seq[i].key] && c.prog[seq[i].key]) return seq[i];
  for (i = 0; i < seq.length; i++) if (cbaReady(seq[i]) && !c.done[seq[i].key]) return seq[i];
  for (i = 0; i < seq.length; i++) if (cbaReady(seq[i]) && cbaStage(seq[i].key) < 2) return seq[i];
  for (i = 0; i < seq.length; i++) if (cbaReady(seq[i])) return seq[i];
  return null;
}
function cbaRounds(k){ return Math.ceil(CBA[k].length / CBA_R); }
function cbaQueue(k, rd){ var q = []; for (var i = rd * CBA_R; i < Math.min(CBA[k].length, (rd + 1) * CBA_R); i++) q.push(i); return q; }
function cbaStart(x){ var st = CBA[x.key], c = cbaS(); var rd = c.prog[x.key] || 0; if (rd >= cbaRounds(x.key)) rd = 0; CB = {key:x.key, x:x, steps:st, rd:rd, queue:cbaQueue(x.key, rd), right:{}, phase:"learn", ans:null, ord:null, xp:0, coins:0, combo:0, best:0, retry:{}, learnAt:0, qAt:0, ansAt:0}; }
function cbaRoundNo(k){ var c = cbaS(), p = c.prog[k] || 0; return p >= cbaRounds(k) ? 0 : p; }
/* topic eggs: 0 none, 1 egg (topic studied in any way, see layEgg), 2 chick (passed Quick fire), 3 hen (rated confident) */
function cbaTopicQQ(k){ var p = k.split("/"), s = BYID[p[0]]; return s && s.qq ? s.qq.filter(function(x){ return x.t === p[1]; }) : []; }
function cbaStage(k){
  var c = cbaS(); if (!c.eggs[k]) return 0;
  var rr = trec(k), conf = rr ? rr.conf : null;
  if (conf === 1) return 3;
  var qq = cbaTopicQQ(k);
  if (qq.length){
    var ans = 0, ok = 0;
    qq.forEach(function(x){ var q = S.qf && S.qf[x.id]; if (q && q.n){ ans++; if (q.b > 0) ok++; } });
    if (ans >= Math.min(5, qq.length) && ok / ans >= 0.7) return 2;
  } else if (rr && conf >= 0.5 && rr.at > c.eggs[k] + 1000) return 2;
  return 1;
}
function cbaAte(id){ var c = cbaS(), t = c.ate[id]; if (!t && id === "corn" && !c.lastAte) t = c.fed; return !!(t && Date.now() - t < CBA_DAY); }
function cbaMood(){ var L = henLife(), hm = henMood(L); hm.L = L; return hm; }
function cbaMoodOld(){
  var c = cbaS(), now = Date.now(), r = c.recent.slice(-10), right = r.filter(function(v){ return v; }).length, fed = c.fed && now - c.fed < CBA_DAY;
  if (c.last && now - c.last > CBA_DAY && !fed) return {m:"sad", e:"🥺", l:"Missing you", t:"I've missed you! One quick round would really cheer me up."};
  if (r.length >= 5 && right / r.length < 0.5) return {m:"sad", e:"😟", l:"A bit worried", t:"Lots of wrong answers lately. Let's read each card carefully. I believe in you!"};
  if (fed) return {m:"happy", e:"😊", l:"Happy", t:({pandan:"That pandan roll was sooo good! I'm full and very happy. Shall we learn something?", latte:"A strawberry matcha latte from LIV Cafe! I feel so fancy. Shall we learn something?"})[c.lastAte] || "Mmm, corn! I'm full and very happy. Shall we learn something?"};
  if (r.length >= 3 && right / r.length >= 0.7 && c.last && now - c.last < CBA_DAY) return {m:"happy", e:"😊", l:"Happy", t:"You've been answering really well. I'm so proud of you!"};
  if (!c.last) return {m:"ok", e:"🙂", l:"Hello!", t:"Hello, I'm Britney! Answer questions to earn coins, then spoil me in the shop."};
  return {m:"ok", e:"🙂", l:"Okay", t:"I'm alright! Play a round or give me some corn to make me happy."};
}

