var ROT_ORDER = ["blp", "dr", "ls", "accounts", "contract", "tort", "legalsys", "ethics", "wills", "trusts", "land", "property", "crimlaw", "crimprac"], ROT_JOIN = {dr: "2026-11-21", ls: "2026-11-22", accounts: "2026-11-25", contract: "2026-11-28", tort: "2026-12-01", legalsys: "2026-12-04", ethics: "2026-12-07", wills: "2026-12-10", trusts: "2026-12-13", land: "2026-12-16", property: "2026-12-19", crimlaw: "2026-12-22", crimprac: "2026-12-27"};
