    '<div class="dfvpic"><img src="' + esc(img.getAttribute("src")) + '" alt="' + esc(img.getAttribute("alt") || "") + '"></div>' +
    (i < figs.length - 1 ? '<button class="btn primary dfvnext" data-dfv="1">Next page ›</button>' : '<button class="btn primary dfvnext" data-dfv="x">Done: back to the strips</button>');
  document.documentElement.classList.add("dfv-on");
