document.addEventListener("click", function(e){
  var a = e.target.closest && e.target.closest(".dfstrip a");
  if (a){ var i = $all(".dfgrid .dfstrip").indexOf(a.closest(".dfstrip")); if (i < 0) return; e.preventDefault(); dfviewShow(i); return; }
  if (!DFVIEW) return;
  var b = e.target.closest && e.target.closest("[data-dfv]");
  if (b){ var v = b.getAttribute("data-dfv"); if (v === "x") dfviewClose(); else dfviewShow((+DFVIEW.getAttribute("data-i") || 0) + (+v)); return; }
  if (e.target === DFVIEW || (e.target.classList && e.target.classList.contains("dfvpic"))) dfviewClose();
});
document.addEventListener("keydown", function(e){
  if (!DFVIEW) return;
  if (e.key === "Escape") dfviewClose();
  else if (e.key === "ArrowRight") dfviewShow((+DFVIEW.getAttribute("data-i") || 0) + 1);
  else if (e.key === "ArrowLeft") dfviewShow((+DFVIEW.getAttribute("data-i") || 0) - 1);
});
window.addEventListener("hashchange", function(){ if (DFVIEW) dfviewClose(); });
function notesWithComic2(src, c){
  /* each cartoon page goes after the notes section whose heading shares most words with the page title (in order) */
  var lines = String(src).split("\n"), chunks = [[]], heads = [""];
  lines.forEach(function(l){ var m = l.match(/^##\s+(.*)$/); if (m){ chunks.push([l]); heads.push(m[1].trim().toLowerCase()); } else chunks[chunks.length - 1].push(l); });
  var words = function(t){ return String(t).toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter(function(w){ return w.length > 3; }); };
  var at = {}, from = 1;
  c.pages.forEach(function(pg, j){
    var pw = words(pg.t), best = -1, bi = -1;
    for (var i = from; i < heads.length; i++){ if (heads[i] === "sources") continue; var hw = words(heads[i]), sc = pw.filter(function(w){ return hw.indexOf(w) >= 0; }).length; if (sc > best){ best = sc; bi = i; } }
    if (best <= 0) bi = Math.min(heads.length - 1, Math.max(from, Math.round((j + 1) * (heads.length - 1) / c.pages.length)));
    if (heads[bi] === "sources") bi = Math.max(1, bi - 1);
    (at[bi] = at[bi] || []).push(j); from = bi;
  });
  var out = "";
  chunks.forEach(function(ch, i){
    out += nsecHTML(ch, i, heads[i]);
    (at[i] || []).forEach(function(j){ out += c2Page(c.pages[j], j, c.pages.length); });
  });
  return out;
}
function notesWithCartoons(src, ct){
  var pages = (ct && ct.pages || []).filter(function(pg){ return pg.after; });
  var lines = String(src).split("\n"), chunks = [[]], heads = [""];
  lines.forEach(function(l){ var m = l.match(/^##\s+(.*)$/); if (m){ chunks.push([l]); heads.push(m[1].trim().toLowerCase()); } else chunks[chunks.length - 1].push(l); });
  var used = {}, out = "";
  chunks.forEach(function(c, i){
    out += nsecHTML(c, i, heads[i]);
    pages.forEach(function(pg, j){ if (used[j]) return; var a = String(pg.after).toLowerCase(); if (heads[i] && heads[i].indexOf(a) === 0){ var last = true; for (var k = i + 1; k < heads.length; k++) if (heads[k].indexOf(a) === 0) last = false; if (last){ out += cpageHTML(pg, j); used[j] = 1; } } });
  });
  pages.forEach(function(pg, j){ if (!used[j]) out += cpageHTML(pg, j); });
  return out;
}
