    '<button type="button" class="nc-btn nc-b2" data-nc="2">👆 What was decided</button><div class="lrn-cs lrn-rule nc-r"><b class="lrn-cl">What was decided</b><div>' + b(c.rule) + '</div></div></div></div>';
  var ln = ncLines(c.body).split("\n");
