document.addEventListener("touchstart", function(e){ var c = e.target.closest && e.target.closest(".lrn-card"); LRNTOUCH = c && !e.target.closest(".lrn-tw, .bistrip, .bigrid") && e.touches.length === 1 ? {x:e.touches[0].clientX, y:e.touches[0].clientY} : null; }, {passive:true});
