    c.pages.forEach(function(pg, i){ if (hasPanels(pg)){ hp += '<div class="cpage">' + panelsHTML(pg) + (pg.note ? '<p class="small">' + inl(pg.note) + '</p>' : '') + '</div>'; return; } hp += '<figure class="cpage"><img src="' + esc(pg.img) + '" alt="' + esc(pg.alt || ("Cartoon page " + (i + 1))) + '" loading="lazy">' + capsHTML(pg) + (pg.note ? '<figcaption>' + inl(pg.note) + '</figcaption>' : '') + '</figure>'; });
    return hp + '</div>';
