    var cy = top;
    (b.pts || []).forEach(function(pt){ mmTspans.bold = false; var L = mmWrap(pt, 306, 15); pts.push({L: L, y: cy}); cy += L.length * LH + 12; });
    var bottom = Math.max(cy, top + 70), mid = (top + bottom) / 2 - 6;
    var hL = mmWrap(b.h, 172, 15, true), bh = Math.max(62, hL.length * 20 + 26);
