      body += '<path class="mmar" d="M' + sx + ',' + mid + ' C' + (sx + 18) + ',' + mid + ' ' + (MMX - 18) + ',' + ty + ' ' + MMX + ',' + ty + '" fill="none" stroke="' + (skin ? c[2] : c[1]) + '" stroke-width="' + (skin ? 2.4 : 2) + '" stroke-dasharray="4 4" marker-end="url(#mma' + (bi % MMCOL.length) + ')"/>';
      mmTspans.bold = false;
