    '<text x="320" y="56" text-anchor="middle" font-size="18" font-weight="700" fill="#24364A">' + tL.map(function(l, i){ return '<tspan x="320" dy="' + (i ? 22 : 0) + '">' + esc(l) + '</tspan>'; }).join("") + '</text>' +
    (sL.length ? '<text x="320" y="' + (62 + tL.length * 22) + '" text-anchor="middle" font-size="12.5" fill="' + (skin ? '#5A3550' : '#5B6E86') + '">' + sL.map(function(l, i){ return '<tspan x="320" dy="' + (i ? 17 : 0) + '">' + esc(l) + '</tspan>'; }).join("") + '</text>' : '');
  var list = '<div class="mmlist"><div class="mmlt">' + esc(m.title || "") + '</div>' + (m.branches || []).map(function(br, bi){ var c = COLS[bi % MMCOL.length]; return '<div class="mmli" style="--mc:' + c[1] + ';--mb:' + c[0] + ';--mh:' + c[2] + '"><div class="mmb" data-b="' + bi + '">' + esc(br.h) + '</div><ul class="mmp" data-b="' + bi + '">' + (br.pts || []).map(function(pt, pi){ return '<li class="mmpt" data-b="' + bi + '" data-p="' + pi + '"' + (FWTEST ? ' tabindex="0" role="button" aria-expanded="false" aria-label="' + esc(br.h) + ': hidden point ' + (pi + 1) + '. Press Enter to reveal."' : '') + '><span class="mmtx">' + esc(pt).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>') + '</span><span class="mmc" aria-hidden="true"></span></li>'; }).join("") + '</ul><div class="mmq" data-b="' + bi + '"></div></div>'; }).join("") + '</div>';
