var MIN_PER_Q = 1.8; // SQE1 from Jan 2027: 153 minutes for each session of 85 questions
var MOCK_LIST = [["FLK1",1],["FLK1",2],["FLK1",3],["FLK2",1],["FLK2",2],["FLK2",3]];
function mkHash(s){ var h = 2166136261; for (var i = 0; i < s.length; i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
