  try { var dcT = dayCount(t); if (dcT.n && dcT.d >= dcT.n && S.celeb !== t){ S.celeb = t; setTimeout(function(){ try { dayCeleb(); save(); } catch(e){} }, 500); } } catch(eC){} /* 21 Nov Monnie: last activity of the day ticked = celebration, once a day */
