/* ---------- Cluckington Palace ---------- */
/* ---------- weather: follows how revision has gone on the last 3 study days ----------
   A study day is "missed" if fewer than half of its tasks were done (feed never unlocked). Days before the save started don't count.
   missed days among the last 3 study days (looking back up to 14 days), minus 1 if half of today's tasks are done:
   0 = sunny, 1 = cloudy, 2 = rainy, 3 = stormy. */
var WX = ["sun", "cloud", "rain", "storm"];
function weatherNow(){
  var g = gameS(), t = ymd(), days = [], missed = 0;
  for (var i = 1; i <= 14 && days.length < 3; i++){
    var ds = addDays(t, -i); if (ds < g.start) break;
    var dc = dayCount(ds); if (!dc.n || bossAway(ds)) continue;
    days.push(ds); if (!g.unl[ds] && dc.d < dc.need) missed++;
  }
  var c = dayCount(t), today = !c.n || c.d >= c.need, lvl = Math.max(0, missed - (today && missed ? 1 : 0)), k = WX[lvl];
  var of = " on " + missed + " of your last " + plural(days.length, "study day");
  var why = lvl === 0 ? (missed ? "Sunny: doing half of today's tasks brought the sun back. Keep it up!" : "Sunny: you're on track with your revision.")
    : (lvl === 1 ? "Cloudy" : lvl === 2 ? "Rainy" : "Stormy") + ": you did less than half your tasks" + of + "." +
      (today ? " Today's tasks have already helped." : " Do half of today's tasks (" + c.need + " of " + c.n + ") to make it better.");
  return {k:k, lvl:lvl, missed:missed, days:days.length, today:today, why:why};
}
function weatherPic(wx){
  if (!wx.lvl) return "";
  var h = '<span class="swxl" aria-hidden="true"><span class="wcl w1"></span><span class="wcl w2"></span>' + (wx.lvl >= 2 ? '<span class="wcl w3"></span>' : '');
  if (wx.lvl >= 2){ h += '<span class="wrain">'; for (var i = 0; i < 26; i++) h += '<i style="left:' + ((i * 37) % 100) + '%;animation-delay:-' + ((i * 0.13) % 1).toFixed(2) + 's"></i>'; h += '</span>'; }
  if (wx.lvl >= 3) h += '<svg class="wbolt" viewBox="0 0 30 60"><path d="M18 0L4 34h10L8 60 27 22H16z" fill="#FFE45C" stroke="#E0A800" stroke-width="1.5" stroke-linejoin="round"/></svg><span class="wflash"></span>';
  return h + '</span>';
}
