var BOSS_CAGE = '<svg class="bcage" viewBox="0 0 100 110" aria-hidden="true"><path d="M8 34Q50 -6 92 34" fill="none" stroke="#5B5249" stroke-width="5" stroke-linecap="round"/><path d="M8 34v70M27 18v86M50 12v92M73 18v86M92 34v70" stroke="#5B5249" stroke-width="4" stroke-linecap="round"/><path d="M4 104h92" stroke="#5B5249" stroke-width="7" stroke-linecap="round"/><circle cx="50" cy="8" r="5" fill="none" stroke="#5B5249" stroke-width="3"/></svg>';
