/* 16:30 (QA): hidden framework cards are keyboard buttons: aria-expanded follows the reveal; Enter or Space reveals */
function fwAria(n){ if (!n || !n.getAttribute || n.getAttribute("role") !== "button" || !n.classList.contains("mmpt")) return; var on = n.classList.contains("show"); n.setAttribute("aria-expanded", on ? "true" : "false");
  if (on){ if (n.hasAttribute("aria-label")){ n.setAttribute("data-al", n.getAttribute("aria-label")); n.removeAttribute("aria-label"); } } else if (n.hasAttribute("data-al")) n.setAttribute("aria-label", n.getAttribute("data-al")); }
document.addEventListener("keydown", function(e){
  if (e.key !== "Enter" && e.key !== " " && e.key !== "Spacebar") return;
  var t = e.target; if (!t || !t.closest || !t.classList || !t.classList.contains("mmpt") || t.getAttribute("role") !== "button" || !t.closest(".mmtest")) return;
  e.preventDefault(); t.dispatchEvent(new MouseEvent("click", {bubbles:true, cancelable:true}));
});
/* framework self-test counter (19 Nov): "3 of 38 revealed" next to the button, counting the version on screen (desktop map or phone list) */
document.addEventListener("click", function(e){
  var t = e.target; if (!t || !t.closest || !t.closest(".mmtest")) return;
  setTimeout(function(){
    var c = document.querySelector(".fwcount"), w = document.querySelector(".fwwrap.mmtest"); if (!c || !w) return;
    var mw = w.querySelector(".mmwrap"), root = mw && mw.offsetParent !== null ? mw : w.querySelector(".mmlist"); if (!root) return;
    var all = root.querySelectorAll(".mmpt").length, sh = root.querySelectorAll(".mmpt.show").length;
    c.textContent = sh >= all ? "All " + all + " revealed! Well done" : sh + " of " + all + " revealed";
    c.classList.toggle("done", sh >= all);
  }, 0);
});

/* comic: shrink bubble text until it fits inside the drawn bubble */
(function(){
  function fit(el){
    var base = parseFloat(el.getAttribute("data-fs") || el.style.fontSize) || 5;
    if (!el.getAttribute("data-fs")) el.setAttribute("data-fs", base);
    var f = base; el.style.fontSize = f + "cqw";
    for (var k = 0; k < 30 && f > 2.2 && (el.scrollHeight > el.clientHeight + 1 || el.scrollWidth > el.clientWidth + 1); k++){ f *= 0.93; el.style.fontSize = f.toFixed(2) + "cqw"; }
  }
  var ro = window.ResizeObserver ? new ResizeObserver(function(es){ es.forEach(function(e){ [].forEach.call(e.target.querySelectorAll(".c2in"), fit); }); }) : null;
  function scan(){ [].forEach.call(document.querySelectorAll(".c2pic"), function(p){ if (p.__c2) return; p.__c2 = 1; if (ro) ro.observe(p); else [].forEach.call(p.querySelectorAll(".c2in"), fit); }); }
  new MutationObserver(function(){ scan(); }).observe(document.documentElement, {childList:true, subtree:true});
  scan();
})();

/* notes: each section is a tap-to-open card (heading always visible) so the page is short; cartoons live in the Cartoon tab */
(function(){
  function wrap(){
    [].forEach.call(document.querySelectorAll(".notes .nsec:not(.nsw)"), function(sec){
      sec.classList.add("nsw");
      var h = sec.querySelector(":scope > h2, :scope > h3"); if (!h || h !== sec.firstElementChild) return;
      if (/big idea/i.test(h.textContent) || sec.querySelector(":scope > .scards")) return;
      var d = document.createElement("details"); d.className = "nsd";
      var sm = document.createElement("summary"); sm.appendChild(h.cloneNode(true)); var hint = document.createElement("span"); hint.className = "nsdh"; hint.textContent = "Tap to open"; sm.appendChild(hint); d.appendChild(sm);
      var n = h.nextSibling; while (n){ var nx = n.nextSibling; d.appendChild(n); n = nx; }
      h.parentNode.replaceChild(d, h);
    });
  }
  new MutationObserver(wrap).observe(document.documentElement, {childList:true, subtree:true});
  wrap();
})();

/* fw-steps (20 Nov): framework walk-through clicks (heading toggles its step; Next opens the next; Show all; Start again) */
(function(){
  function setOpen(li, on){ li.classList.toggle("open", on); var b = li.querySelector(".fwk-h"), d = li.querySelector(".fwk-d"); if (b) b.setAttribute("aria-expanded", on ? "true" : "false"); if (d){ if (on) d.removeAttribute("hidden"); else d.setAttribute("hidden", ""); } }
  function sync(w){ var li = w.querySelectorAll(".fwk-step"), n = 0;
    [].forEach.call(li, function(x, i){ if (x.classList.contains("open")) n++; var nx = x.querySelector(".fwk-next"); if (nx) nx.hidden = !!(li[i + 1] && li[i + 1].classList.contains("open")); var pv = x.querySelector(".fwk-prev"); if (pv) pv.hidden = !!(li[i - 1] && li[i - 1].classList.contains("open")); });
    var c = w.querySelector(".fwk-count"); if (c) c.textContent = n >= li.length ? "All " + li.length + " steps open" : n + " of " + li.length + " steps open";
    var a = w.querySelector(".fwk-all"); if (a) a.disabled = n >= li.length; }
  document.addEventListener("click", function(e){
    var t = e.target; if (!t || !t.closest) return;
    var w = t.closest(".fwalk"); if (!w) return;
    var steps = [].slice.call(w.querySelectorAll(".fwk-step"));
    if (t.closest(".fwk-h")){ var li = t.closest(".fwk-step"); setOpen(li, !li.classList.contains("open")); }
    else if (t.closest(".fwk-next")){ var cur = t.closest(".fwk-step"), nx = steps[steps.indexOf(cur) + 1]; if (nx){ setOpen(cur, false); /* 15:58 (QA): the finished step folds away */ setOpen(nx, true); var hb = nx.querySelector(".fwk-h"); if (hb) try { hb.focus({preventScroll:true}); } catch(ex){} var r = nx.getBoundingClientRect(); if (r.bottom > innerHeight) try { nx.scrollIntoView({block:"nearest", behavior:"smooth"}); } catch(ex){ nx.scrollIntoView(false); } } }
    else if (t.closest(".fwk-prev")){ var cu = t.closest(".fwk-step"), pv = steps[steps.indexOf(cu) - 1]; if (pv){ setOpen(cu, false); setOpen(pv, true); var hp = pv.querySelector(".fwk-h"); if (hp) try { hp.focus({preventScroll:true}); } catch(ex){} var rp = pv.getBoundingClientRect(); if (rp.top < 0 || rp.bottom > innerHeight) try { pv.scrollIntoView({block:"nearest", behavior:"smooth"}); } catch(ex){ pv.scrollIntoView(true); } } } /* 16:30 (QA): ‹ Previous step */
    else if (t.closest(".fwk-all")) steps.forEach(function(x){ setOpen(x, true); });
    else if (t.closest(".fwk-reset")){ steps.forEach(function(x, i){ setOpen(x, i === 0); }); try { w.scrollIntoView({block:"nearest", behavior:"smooth"}); } catch(ex){} var h0 = steps[0] && steps[0].querySelector(".fwk-h"); if (h0) try { h0.focus({preventScroll:true}); } catch(ex){} }
    else return;
    sync(w);
  });
})();

/* numbered-list reveal + exam-question sweets (20 Nov): plain DOM toggling */
(function(){
  function rlSet(li, on){ li.classList.toggle("open", on); var n = li.querySelector(".rl-n"), l = li.querySelector(".rl-lead"), d = li.querySelector(".rl-d"); if (n) n.setAttribute("aria-expanded", on ? "true" : "false"); if (l) l.hidden = on; if (d) d.hidden = !on; }
  function rlSync(w){ var it = w.querySelectorAll(".rl-i"), open = w.querySelectorAll(".rl-i.open").length, all = open >= it.length;
    var nx = w.querySelector(".rl-next"), sa = w.querySelector(".rl-all"), rs = w.querySelector(".rl-reset"); if (nx) nx.hidden = all; if (sa) sa.hidden = all; if (rs) rs.hidden = !all; }
  function pop(btn, delay){ if (!btn || btn.classList.contains("pop")) return; setTimeout(function(){ btn.classList.add("pop"); setTimeout(function(){ btn.hidden = true; }, 420); }, delay || 0); }
  document.addEventListener("click", function(e){
    var t = e.target; if (!t || !t.closest) return;
    var w = t.closest(".revlist");
    if (w){ var its = [].slice.call(w.querySelectorAll(".rl-i"));
      if (t.closest(".rl-n")){ var li = t.closest(".rl-i"); rlSet(li, !li.classList.contains("open")); }
      else if (t.closest(".rl-lead")){ var li2 = t.closest(".rl-i"); rlSet(li2, true); try { li2.querySelector(".rl-n").focus({preventScroll:true}); } catch(ex){} }
      else if (t.closest(".rl-next")){ var nx = its.filter(function(x){ return !x.classList.contains("open"); })[0]; if (nx) rlSet(nx, true); }
      else if (t.closest(".rl-all")) its.forEach(function(x){ rlSet(x, true); });
      else if (t.closest(".rl-reset")) its.forEach(function(x, i){ rlSet(x, i === 0); });
      else return;
      rlSync(w); return; }
    var q = t.closest(".exq"); if (!q) return;
    var sb = t.closest(".exq-s");
    if (sb){ pop(sb); var tx = sb.parentNode.querySelector(".exq-t"); if (tx) setTimeout(function(){ try { tx.focus({preventScroll:true}); } catch(ex){} }, 430); }
    else if (t.closest(".exq-all")){ [].forEach.call(q.querySelectorAll(".exq-s:not(.pop)"), function(x, i){ pop(x, i * 70); }); t.closest(".exq-all").hidden = true; return; }
    else return;
    setTimeout(function(){ if (!q.querySelector(".exq-s:not(.pop)")){ var a = q.querySelector(".exq-all"); if (a) a.hidden = true; } }, 0);
  });
})();

