/* "Report a mistake" (added 20 Nov 2026). A small flag button on note, card and question pages.
   Flags are saved in this browser only (localStorage "sqe_reports") and can be downloaded or emailed as a list.
   Self-contained: lives outside #app so app.js re-renders don't touch it. */
(function(){
  var KEY = "sqe_reports";
  var SHOW = /^(home|today|plan|syllabus|subject|progress|settings|frameworks|cartoons|podcasts|log|hours|mount|palace|topic|cards|quick|questions|play|mock|cba|sra|weak|boss|scene|town|shop|learn|room|tips|official)$/; /* 18:25 (QA): on every content tab */
  function load(){ try { var v = JSON.parse(localStorage.getItem(KEY) || "[]"); return Array.isArray(v) ? v : []; } catch(e){ return []; } }
  function store(a){ try { localStorage.setItem(KEY, JSON.stringify(a)); return true; } catch(e){ return false; } }
  function r0(){ return ((location.hash || "#/home").replace(/^#\/?/, "").split("/")[0] || "home"); }
  function txt(el){ return el ? (el.innerText || el.textContent || "").replace(/\s+/g, " ").trim() : ""; }
  function where(){
    var app = document.getElementById("app"), main = app && (app.querySelector(".wrap") || app);
    var head = main ? txt(main.querySelector("h1, h2")) || txt(main.querySelector(".qmeta, .qzcard .pill, .tag, .scn h3, h3")) : "";
    var r0 = (location.hash.split("/")[1] || "home"), pn = ({play:"Model Q&A", questions:"Model Q&A", quick:"Quick fire", cards:"Revision cards", topic:"Topic notes", scene:"Peckham stop", town:"Peckham", mount:"The Mount", palace:"Peckham map", today:"Today", boss:"Bert's fight", mock:"Mock exam"})[r0] || "";
    head = head.replace(/[·|,]?\s*score\s*\d+/i, "").replace(/^[^A-Za-z0-9]+/, "").trim();
    if (r0 === "cards"){ var dk = main && txt(main.querySelector(".cstop-tx, .inner .subj, h2")); if (dk && head.indexOf(dk) < 0) head = dk + " · " + head; }
    if (pn && head.indexOf(pn) !== 0) head = pn + (head ? " · " + head : ""); if (!head) head = r0; /* 17:30 (QA): lead with the page name, deck name for cards, no "score 0" */
    var q = main ? txt(main.querySelector(".qtext, .qstem, .stem, .qq, .qf, .cbaq, .bq, .bossq, .q, .fcq, .cardq, .fc .face, .front, .scn-pop h3, .hlpara")) : "";
    return { page: location.hash || "#/home", heading: head.slice(0, 140), item: q.slice(0, 300) };
  }
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function asText(a){
    return "SQE1 site: reported mistakes (" + a.length + ")\n\n" + a.map(function(x, i){
      return (i + 1) + ". " + x.when + "\n   Page: " + x.page + (x.heading ? "\n   Section: " + x.heading : "") + (x.item ? "\n   Item: " + x.item : "") + (x.sel ? "\n   Highlighted: " + x.sel : "") + "\n   What's wrong: " + x.note;
    }).join("\n\n");
  }
  var css = ".rpt-btn{position:fixed;left:10px;bottom:10px;z-index:9000;font:600 12px/1 system-ui,sans-serif;padding:6px 10px;border-radius:14px;border:1px solid rgba(0,0,0,.18);background:rgba(255,255,255,.85);color:#555;cursor:pointer;opacity:.55;transition:opacity .15s}" +
    ".rpt-btn:hover,.rpt-btn:focus{opacity:1}" +
    /* 14:25 (QA pass 1): solid tab on the left edge, in its own space, instead of a see-through pill over the page */
    ".rpt-btn{left:0;bottom:22px;opacity:1;writing-mode:vertical-rl;transform:rotate(180deg);padding:12px 7px;border-radius:0 8px 8px 0;border:1.5px solid #10294A;border-left:0;background:#fff;color:#10294A;font:700 13px/1 Calibri,Carlito,system-ui,sans-serif;box-shadow:none}" +
    ".rpt-btn:hover,.rpt-btn:focus{background:#FFF3C4}" +
    ".rpt-pan{left:34px;bottom:22px}" +
    ".rpt-pan{position:fixed;left:10px;bottom:44px;z-index:9001;width:min(360px,calc(100vw - 20px));max-height:70vh;overflow:auto;background:#fff;color:#222;border:1px solid #ccc;border-radius:12px;box-shadow:0 6px 24px rgba(0,0,0,.2);padding:12px;font:15px/1.4 Calibri,Carlito,system-ui,sans-serif}" +
    ".rpt-pan h3{margin:0 0 6px;font-size:15px}.rpt-pan textarea{width:100%;box-sizing:border-box;min-height:70px;margin-top:8px;display:block;font:inherit;padding:6px;border:1px solid #bbb;border-radius:6px}" +
    ".rpt-pan .rpt-row{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.rpt-pan button{font:600 13px Calibri,Carlito,system-ui,sans-serif;padding:6px 10px;border-radius:8px;border:1px solid #bbb;background:#f4f4f4;cursor:pointer}" +
    ".rpt-pan button.rpt-go{background:#4A3B6B;color:#fff;border-color:#4A3B6B}.rpt-pan .rpt-mut{color:#666;font-size:12px}.rpt-pan ol{padding-left:18px;margin:6px 0}.rpt-pan li{margin:4px 0;font-size:12px}" +
    ".rpt-pan .rpt-x{float:right;border:0;background:none;font-size:16px;padding:0 4px}.rpt-bd{position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,.45)}.rpt-pan.rpt-pan{left:50%;top:50%;bottom:auto;transform:translate(-50%,-50%);width:min(440px,calc(100vw - 32px));max-height:80vh;box-shadow:0 10px 30px rgba(0,0,0,.3)}";
  var st = document.createElement("style"); st.textContent = css; document.head.appendChild(st);
  var btn = document.createElement("button"); btn.className = "rpt-btn"; btn.type = "button"; btn.textContent = "⚑ Report a mistake"; btn.title = "Spotted something wrong? Flag it here.";
  var pan = null, lastSel = "";
  document.addEventListener("selectionchange", function(){ try { var s = String(window.getSelection() || "").replace(/\s+/g, " ").trim(); if (s && !(pan && pan.contains(document.activeElement))) lastSel = s.slice(0, 300); } catch(e){} });
  var bd = null;
  function close(){ if (pan){ pan.remove(); pan = null; } if (bd){ bd.remove(); bd = null; } }
  function open(msg){
    close(); var a = load(), w = where();
    pan = document.createElement("div"); pan.className = "rpt-pan";
    pan.innerHTML = '<button class="rpt-x" data-r="x" aria-label="Close">✕</button><h3>Report a mistake</h3>' +
      '<div class="rpt-mut">On: ' + esc(w.heading || w.page) + (w.item ? '<br>Question: “' + esc(w.item.slice(0, 110)) + (w.item.length > 110 ? "…" : "") + '”' : '') + (lastSel ? '<br>Highlighted: “' + esc(lastSel.slice(0, 120)) + (lastSel.length > 120 ? "…" : "") + '”' : '') + '</div>' +
      '<textarea id="rpt-note" placeholder="What looks wrong? (A few words is fine.)"></textarea>' +
      '<div class="rpt-row"><button class="rpt-go" data-r="save">Save</button><button data-r="x">Cancel</button></div>' +
      (msg ? '<p class="rpt-mut" style="color:#2a7a2a">' + esc(msg) + '</p>' : '') +
      '<hr style="border:0;border-top:1px solid #eee;margin:10px 0"><b>Your saved reports (' + a.length + ')</b>' +
      (a.length ? '<ol>' + a.map(function(x, i){ return '<li>' + esc(x.note) + ' <span class="rpt-mut">(' + esc(x.heading || x.page) + ')</span> <button data-r="del" data-i="' + i + '" style="padding:0 6px;font-size:11px">delete</button></li>'; }).join("") + '</ol>' +
        '<div class="rpt-row"><button data-r="mail">Email the list</button><button data-r="dl">Download the list</button><button data-r="copy">Copy</button></div>' : '<p class="rpt-mut">None yet.</p>');
    bd = document.createElement("div"); bd.className = "rpt-bd"; bd.addEventListener("click", close); document.body.appendChild(bd); /* 17:05 (QA): dimmed backdrop, tap it to close */
    document.body.appendChild(pan);
    var ta = pan.querySelector("#rpt-note"); if (ta) ta.focus();
  }
  btn.addEventListener("click", function(){ if (pan) close(); else open(); });
  document.addEventListener("click", function(e){
    var b = e.target.closest && e.target.closest(".rpt-pan [data-r]"); if (!b) return;
    var k = b.getAttribute("data-r"), a = load();
    if (k === "x") close();
    else if (k === "save"){
      var n = (pan.querySelector("#rpt-note").value || "").trim(); if (!n){ pan.querySelector("#rpt-note").focus(); return; }
      var w = where(); a.push({ when: new Date().toLocaleString("en-GB"), page: w.page, heading: w.heading, item: w.item, sel: lastSel, note: n.slice(0, 1000) });
      lastSel = ""; open(store(a) ? "Saved on this device, with the question attached. To send your saved reports to Monnie, tap \"Email the list\" below." : "Couldn't save in this browser.");
    }
    else if (k === "del"){ a.splice(+b.getAttribute("data-i"), 1); store(a); open(); }
    else if (k === "mail"){ location.href = "mailto:?subject=" + encodeURIComponent("SQE1 site: mistakes I spotted") + "&body=" + encodeURIComponent(asText(a).slice(0, 1800)); }
    else if (k === "dl"){ try { var u = URL.createObjectURL(new Blob([asText(a)], {type:"text/plain"})), l = document.createElement("a"); l.href = u; l.download = "sqe1-reported-mistakes.txt"; document.body.appendChild(l); l.click(); setTimeout(function(){ URL.revokeObjectURL(u); l.remove(); }, 1000); } catch(err){} }
    else if (k === "copy"){ try { navigator.clipboard.writeText(asText(a)); b.textContent = "Copied"; } catch(err){} }
  });
  function sync(){ var on = SHOW.test(r0()); if (on && !btn.isConnected) document.body.appendChild(btn); if (!on){ if (btn.isConnected) btn.remove(); close(); } }
  window.addEventListener("hashchange", sync);
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", sync); else sync();
})();
